window.receiveProjectSource({"path": "src/microservices/web_extraction/services/helpers/source_classification.py", "lines": ["\"\"\"Source-classification helpers for Web Extraction layer-two processing.", "", "Rollback contract", "-----------------", "Helpers in this module follow a layered ownership model for transactional", "cleanup, so callers know who is responsible for what:", "", "- **Committing helpers** (``persist_layer_two_retry_context``,", "  ``attach_article_to_group``) own their own rollback. On commit failure or", "  unexpected exception they invoke ``safe_rollback(db)`` before re-raising as", "  a ``DatabaseCommitException`` / ``DatabaseWriteException``. They do *not*", "  roll back when re-raising a ``DatabaseWriteException`` that was thrown by a", "  nested helper \u2014 that helper is assumed to have already cleaned up or to be", "  a flush-only helper whose cleanup belongs to the outer committing scope.", "", "- **Flush-only helpers** (``_upsert_source_classification_record``,", "  ``_create_singleton_group_locked``) never commit and never roll back.", "  Their writes participate in the caller's transaction, so the caller's", "  commit or rollback is what publishes or discards them.", "", "- **Resolve helpers** (``_resolve_or_materialize_group_for_article``) may", "  call flush-only helpers and therefore inherit the flush-only contract:", "  they do not commit, and the caller is responsible for committing (in the", "  non-recovery path, via ``persist_layer_two_retry_context``; in the", "  recovery-fallback path, via an explicit ``db.commit()``).", "", "The net effect: each transaction has exactly one \"owning\" function that is", "responsible for either committing or rolling back, and the nested helpers", "trust that ownership rather than each calling rollback defensively.", "\"\"\"", "", "from contextlib import AsyncExitStack", "from datetime import UTC, datetime", "from typing import Any, Dict, Optional", "from uuid import UUID", "", "from sqlalchemy import delete, func, select, update", "from sqlalchemy.dialects.postgresql import insert", "from sqlalchemy.ext.asyncio import AsyncSession", "", "from common.exceptions.exceptions import (", "    DatabaseCommitException,", "    DatabaseWriteException,", ")", "from common.utils.advisory_lock import pg_advisory_xact_lock, url_to_lock_key", "from common.utils.db_session import safe_rollback", "from microservices.web_extraction.logging import logger", "from microservices.web_extraction.models import (", "    LayerTwoRetryState,", "    SourceClassification,", "    SourceClassificationGroup,", "    WebExtractionResponse,", "    ZyteArticle,", ")", "", "CLASSIFICATION_METHOD_VECTOR = \"vector-article-aggregate\"", "CLASSIFICATION_METHOD_LAZY_SINGLETON = \"lazy-singleton\"", "", "# Bound on how many times ``attach_article_to_group`` will chase a moving", "# matched-article group during convergence. A 3-way race can leave the", "# matched article in a third group that neither input to our merge", "# anticipated; we re-read and re-merge to chase it. Under advisory locks", "# the chase should terminate in 1-2 hops; the cap prevents unbounded", "# work under pathological concurrent scheduling.", "_MAX_CONVERGENCE_ITERATIONS = 3", "", "", "async def get_source_classification_for_article(", "    db: AsyncSession, article_id: UUID", ") -> Optional[SourceClassification]:", "    \"\"\"Return source-classification row for a given article, if one exists.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param article_id: Article id whose classification row to read.", "    :type article_id: UUID", "    :return: Persisted classification row, or None when no row exists yet.", "    :rtype: Optional[SourceClassification]", "    \"\"\"", "    result = await db.execute(", "        select(SourceClassification).where(SourceClassification.article_id == article_id)", "    )", "    return result.scalar_one_or_none()", "", "", "async def read_layer_two_retry_context(", "    db: AsyncSession,", "    response_id: UUID,", ") -> Optional[LayerTwoRetryState]:", "    \"\"\"Read persisted retry context row for a response id.", "", "    Returning the ORM row (rather than a positional tuple) lets callers read", "    fields by name and keeps the contract stable when the row grows.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param response_id: Response id whose retry context to read.", "    :type response_id: UUID", "    :return: Persisted retry-state row, or None when no row exists yet.", "    :rtype: Optional[LayerTwoRetryState]", "    \"\"\"", "    return await db.get(LayerTwoRetryState, response_id)", "", "", "async def persist_layer_two_retry_context(", "    db: AsyncSession,", "    *,", "    response_id: UUID,", "    similarity_as_of: Optional[datetime] = None,", "    frozen_syndication_group_id: Optional[UUID] = None,", ") -> None:", "    \"\"\"Persist retry context for deterministic layer-two retries.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param response_id: Response id keying the retry-state row.", "    :type response_id: UUID", "    :param similarity_as_of: Snapshot cutoff to freeze, when provided.", "    :type similarity_as_of: Optional[datetime]", "    :param frozen_syndication_group_id: Group id to freeze, when provided.", "    :type frozen_syndication_group_id: Optional[UUID]", "    :raises DatabaseWriteException: On commit failure or unexpected error.", "    \"\"\"", "    try:", "        existing = await db.get(LayerTwoRetryState, response_id)", "        if existing is None:", "            existing = LayerTwoRetryState(response_id=response_id)", "            db.add(existing)", "        if similarity_as_of is not None:", "            existing.similarity_as_of = similarity_as_of", "        if frozen_syndication_group_id is not None:", "            existing.frozen_syndication_group_id = frozen_syndication_group_id", "        await db.commit()", "    except DatabaseWriteException:", "        raise", "    except Exception as e:", "        await safe_rollback(db)", "        raise DatabaseWriteException(", "            f\"Failed to persist layer-two retry context (caused by >>> {e!r})\",", "            response_id=str(response_id),", "        ) from e", "", "", "async def ensure_layer_two_retry_similarity_cutoff(", "    db: AsyncSession,", "    *,", "    response_id: UUID,", "    existing_response: Optional[WebExtractionResponse],", "    current_cutoff: Optional[datetime],", ") -> datetime:", "    \"\"\"Ensure similarity-as-of cutoff is persisted at classification time.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param response_id: Response id keying retry context.", "    :type response_id: UUID", "    :param existing_response: Stored response row when this is a retry, else None.", "    :type existing_response: Optional[WebExtractionResponse]", "    :param current_cutoff: Already-resolved cutoff, returned as-is when set.", "    :type current_cutoff: Optional[datetime]", "    :return: Effective similarity-as-of cutoff for classification.", "    :rtype: datetime", "    \"\"\"", "    if current_cutoff is not None:", "        return current_cutoff", "", "    cutoff = existing_response.created_at if existing_response is not None else datetime.now(tz=UTC)", "    await persist_layer_two_retry_context(", "        db,", "        response_id=response_id,", "        similarity_as_of=cutoff,", "    )", "    return cutoff", "", "", "async def _upsert_source_classification_record(", "    db: AsyncSession,", "    *,", "    article_id: UUID,", "    syndication_group_id: UUID,", "    similarity_score: Optional[float],", "    matched_article_id: Optional[UUID],", "    classification_method: str,", "    match_info: Optional[Dict[str, Any]] = None,", ") -> SourceClassification:", "    \"\"\"Upsert one source-classifications row and return the persisted ORM row.", "", "    ``doc_id`` is intentionally not handled here \u2014 it is owned by the", "    entity-classification sync path (``entity_classification.services.", "    helpers.external.sync``) and written directly against the row.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param article_id: Article id being classified.", "    :type article_id: UUID", "    :param syndication_group_id: Group id this row attaches to.", "    :type syndication_group_id: UUID", "    :param similarity_score: Best-match similarity score, when known.", "    :type similarity_score: Optional[float]", "    :param matched_article_id: Article matched for syndication, when applicable.", "    :type matched_article_id: Optional[UUID]", "    :param classification_method: Identifier for the classification approach used.", "    :type classification_method: str", "    :param match_info: Optional audit blob persisted to the row's ``match_info``", "        JSONB. Carries chunk match details and any borderline-verifier verdict.", "        ``None`` skips the column on insert and leaves it untouched on upsert.", "    :type match_info: Optional[Dict[str, Any]]", "    :return: Persisted classification row.", "    :rtype: SourceClassification", "    :raises DatabaseWriteException: When the upsert fails or the row cannot be reloaded.", "    \"\"\"", "    values: Dict[str, Any] = {", "        \"article_id\": article_id,", "        \"syndication_group_id\": syndication_group_id,", "        \"similarity_score\": similarity_score,", "        \"matched_article_id\": matched_article_id,", "        \"classification_method\": classification_method,", "    }", "    if match_info is not None:", "        values[\"match_info\"] = match_info", "    try:", "        insert_stmt = insert(SourceClassification).values(values)", "        update_set: Dict[str, Any] = {", "            \"syndication_group_id\": insert_stmt.excluded.syndication_group_id,", "            \"similarity_score\": insert_stmt.excluded.similarity_score,", "            \"matched_article_id\": insert_stmt.excluded.matched_article_id,", "            \"classification_method\": insert_stmt.excluded.classification_method,", "            \"updated_at\": func.now(),", "        }", "        if match_info is not None:", "            update_set[\"match_info\"] = insert_stmt.excluded.match_info", "        stmt = insert_stmt.on_conflict_do_update(", "            constraint=\"uq_webex_source_classifications_article_id\",", "            set_=update_set,", "        ).returning(SourceClassification.id)", "        classification_id = (await db.execute(stmt)).scalar_one()", "        row = await db.get(SourceClassification, classification_id)", "        if row is None:", "            raise DatabaseWriteException(", "                \"SourceClassification upsert returned an unknown row id\",", "                article_id=article_id,", "            )", "        return row", "    except DatabaseWriteException:", "        raise", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to upsert source classification row (caused by >>> {e!r})\",", "            article_id=article_id,", "            syndication_group_id=syndication_group_id,", "            matched_article_id=matched_article_id,", "        ) from e", "", "", "def _pick_primary_article_id(", "    article_ids: list[UUID],", "    published_at_by_article: Dict[UUID, Optional[datetime]],", "    fallback_created_at_by_article: Dict[UUID, datetime],", ") -> UUID:", "    \"\"\"Select group primary article by earliest publish date.", "", "    :param article_ids: Candidate member article ids. Must be non-empty; caller is responsible for short-circuiting when the group has no members.", "    :type article_ids: list[UUID]", "    :param published_at_by_article: Earliest known publish dates from Zyte rows.", "    :type published_at_by_article: Dict[UUID, Optional[datetime]]", "    :param fallback_created_at_by_article: Classification-row created_at fallback.", "    :type fallback_created_at_by_article: Dict[UUID, datetime]", "    :return: Article id chosen as primary.", "    :rtype: UUID", "    :raises ValueError: When ``article_ids`` is empty.", "    \"\"\"", "    if not article_ids:", "        raise ValueError(", "            \"_pick_primary_article_id requires at least one article id; \"", "            \"caller must short-circuit when the group has no members\"", "        )", "", "    def _sort_key(article_id: UUID) -> tuple[int, datetime, datetime, str]:", "        published_at = published_at_by_article.get(article_id)", "        created_at = fallback_created_at_by_article[article_id]", "        if published_at is None:", "            # ``datetime.max`` is a sentinel so undated articles sort *after*", "            # any real publish date \u2014 the leading 1 already enforces the", "            # \"dated beats undated\" tier, but the field must still be a", "            # datetime for the tuple's element types to stay homogeneous.", "            return (1, datetime.max.replace(tzinfo=UTC), created_at, str(article_id))", "        return (0, published_at, created_at, str(article_id))", "", "    return min(article_ids, key=_sort_key)", "", "", "async def _new_member_could_displace_primary(", "    db: AsyncSession, syndication_group_id: UUID, new_article_id: UUID", ") -> bool:", "    \"\"\"Return True iff the new attachee could displace the group's current primary.", "", "    Optimization for the hot-news burst case: ``reevaluate_group_primary`` is", "    O(group_size) inside a ``SELECT FOR UPDATE`` on the parent group, so a", "    chain of N concurrent attaches to one group costs O(N\u00b2) cumulative", "    wallclock. Primaries are selected by EARLIEST ``date_published``", "    (with classification ``created_at`` as tie-breaker / fallback), so when", "    the new member's ``date_published`` is strictly later than the current", "    primary's, no recompute is needed and we can short-circuit.", "", "    Returns True (forcing a full recompute) on any uncertainty:", "", "    - Group has no resolved primary yet (defensive).", "    - Current primary has no Zyte ``date_published`` but the new article does", "      \u2014 the new article jumps the \"has dated row beats undated\" ordering.", "    - New article has no Zyte ``date_published`` *and* the current primary", "      also has none \u2014 the tie-breaker (classification ``created_at``) lives", "      inside ``_pick_primary_article_id`` and must run.", "    - Both dated, new <= current \u2014 could displace via equality (tie-breaker).", "", "    The only branch that returns False is \"both dated AND new > current\",", "    which is the typical case for syndication coverage of a story already", "    in the group (later wire-service pickup of the same event).", "    \"\"\"", "    primary_article_id = (", "        await db.execute(", "            select(SourceClassificationGroup.primary_article_id).where(", "                SourceClassificationGroup.id == syndication_group_id", "            )", "        )", "    ).scalar_one_or_none()", "    if primary_article_id is None:", "        return True", "", "    dates = (", "        await db.execute(", "            select(ZyteArticle.article_id, func.min(ZyteArticle.date_published))", "            .where(", "                ZyteArticle.article_id.in_([primary_article_id, new_article_id]),", "                ZyteArticle.date_published.is_not(None),", "            )", "            .group_by(ZyteArticle.article_id)", "        )", "    ).all()", "    date_by_article: Dict[UUID, datetime] = {", "        article_id: published_at for article_id, published_at in dates", "    }", "", "    current_date = date_by_article.get(primary_article_id)", "    new_date = date_by_article.get(new_article_id)", "", "    # Only safe-to-skip case: both dated and the new member is strictly later.", "    if current_date is not None and new_date is not None and new_date > current_date:", "        return False", "    # Current dated, new undated: current beats undated by ordering \u2014 new can't displace.", "    if current_date is not None and new_date is None:", "        return False", "    return True", "", "", "async def reevaluate_group_primary(db: AsyncSession, syndication_group_id: UUID) -> None:", "    \"\"\"Recompute the primary article for a syndication group.", "", "    Updates ``source_classification_groups.primary_article_id``, the authoritative", "    source of group-primary identity.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param syndication_group_id: Group id whose primary should be recomputed.", "    :type syndication_group_id: UUID", "    \"\"\"", "    rows = (", "        (", "            await db.execute(", "                select(SourceClassification).where(", "                    SourceClassification.syndication_group_id == syndication_group_id", "                )", "            )", "        )", "        .scalars()", "        .all()", "    )", "    if not rows:", "        # Group has no members \u2014 nothing to recompute. Leave the existing", "        # ``primary_article_id`` alone (NULLing it would risk downstream FK", "        # surprises) and skip the subsequent Zyte-date lookup.", "        return", "", "    article_ids = [row.article_id for row in rows]", "    classification_created_at: Dict[UUID, datetime] = {", "        row.article_id: row.created_at for row in rows", "    }", "    zyte_dates = (", "        await db.execute(", "            select(ZyteArticle.article_id, func.min(ZyteArticle.date_published))", "            .where(", "                ZyteArticle.article_id.in_(article_ids),", "                ZyteArticle.date_published.is_not(None),", "            )", "            .group_by(ZyteArticle.article_id)", "        )", "    ).all()", "    published_at_by_article: Dict[UUID, Optional[datetime]] = {", "        article_id: published_at for article_id, published_at in zyte_dates", "    }", "", "    primary_article_id = _pick_primary_article_id(", "        article_ids,", "        published_at_by_article,", "        classification_created_at,", "    )", "", "    await db.execute(", "        update(SourceClassificationGroup)", "        .where(SourceClassificationGroup.id == syndication_group_id)", "        .values(", "            primary_article_id=primary_article_id,", "            updated_at=func.now(),", "        )", "    )", "", "", "async def _merge_syndication_groups(", "    db: AsyncSession,", "    *,", "    group_id_a: UUID,", "    group_id_b: UUID,", ") -> UUID:", "    \"\"\"Merge two syndication groups under one canonical and return the winner id.", "", "    Called from ``attach_article_to_group`` when a crossed-write race causes", "    two workers to land their respective articles in different groups before", "    either attach completes. Without this merge, the two singleton groups", "    persist as a split \u2014 see DAT-6369 notes for the failure mode.", "", "    Determinism:", "", "    - Winner is the lower-UUID-by-string of the two groups. This makes the", "      merge idempotent across concurrent attempts: two workers racing to", "      merge the same pair pick the same winner and the second one's merge", "      becomes a no-op (its loser is already gone).", "    - Both groups are taken with ``SELECT \u2026 FOR UPDATE`` in UUID order so", "      concurrent merges that overlap on a group serialize cleanly without", "      deadlocking.", "", "    Flush-only contract:", "", "    - This helper participates in the caller's transaction; it does not", "      commit. Errors propagate as ``DatabaseWriteException``.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param group_id_a: One of the two group ids to merge.", "    :type group_id_a: UUID", "    :param group_id_b: The other group id to merge.", "    :type group_id_b: UUID", "    :return: Id of the surviving (winner) group after merge.", "    :rtype: UUID", "    :raises DatabaseWriteException: On underlying write failure.", "    \"\"\"", "    if group_id_a == group_id_b:", "        return group_id_a", "", "    winner_id, loser_id = sorted([group_id_a, group_id_b], key=str)", "", "    try:", "        # Lock both groups under FOR UPDATE in deterministic UUID order so", "        # concurrent merges touching the same pair serialize without deadlock.", "        sorted_ids = [winner_id, loser_id]", "        rows = (", "            (", "                await db.execute(", "                    select(SourceClassificationGroup)", "                    .where(SourceClassificationGroup.id.in_(sorted_ids))", "                    .order_by(SourceClassificationGroup.id)", "                    .with_for_update()", "                )", "            )", "            .scalars()", "            .all()", "        )", "        by_id: Dict[UUID, SourceClassificationGroup] = {g.id: g for g in rows}", "        winner = by_id.get(winner_id)", "        loser = by_id.get(loser_id)", "", "        # Concurrent merge may have already happened. Three possibilities:", "        if winner is None and loser is None:", "            raise DatabaseWriteException(", "                \"Both groups gone when attempting merge \u2014 concurrent merges \"", "                \"produced unexpected state\",", "                group_id_a=str(group_id_a),", "                group_id_b=str(group_id_b),", "            )", "        if winner is None:", "            # Winner already consumed by a prior merge into something else;", "            # the loser is the only one still standing. Return it as the", "            # surviving group so the caller attaches there. This requires a", "            # genuine 3-way race (which advisory locks make unlikely), and", "            # the caller may end up in a different group than the matched", "            # article's current group \u2014 log so any silent fragmentation is", "            # observable downstream.", "            logger.warning(", "                \"Merge encountered missing winner \u2014 possible 3-way race; \"", "                \"attaching to surviving loser group\",", "                winner_group_id=str(winner_id),", "                loser_group_id=str(loser_id),", "            )", "            return loser_id", "        if loser is None:", "            # Already merged in a prior pass. Idempotent return.", "            return winner_id", "", "        loser_member_count = loser.member_count", "", "        # Move every classification row from loser to winner.", "        await db.execute(", "            update(SourceClassification)", "            .where(SourceClassification.syndication_group_id == loser_id)", "            .values(syndication_group_id=winner_id)", "        )", "", "        # Bump winner's member_count by what the loser carried.", "        await db.execute(", "            update(SourceClassificationGroup)", "            .where(SourceClassificationGroup.id == winner_id)", "            .values(", "                member_count=SourceClassificationGroup.member_count + loser_member_count,", "                updated_at=func.now(),", "            )", "        )", "", "        # Recompute primary across the merged member set.", "        await reevaluate_group_primary(db, winner_id)", "", "        # Drop the now-empty loser group row.", "        await db.execute(", "            delete(SourceClassificationGroup).where(SourceClassificationGroup.id == loser_id)", "        )", "", "        logger.info(", "            \"Merged syndication groups\",", "            winner_group_id=str(winner_id),", "            loser_group_id=str(loser_id),", "            merged_member_count=loser_member_count,", "        )", "        return winner_id", "    except DatabaseWriteException:", "        raise", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to merge syndication groups (caused by >>> {e!r})\",", "            winner_group_id=str(winner_id),", "            loser_group_id=str(loser_id),", "        ) from e", "", "", "async def _create_singleton_group_locked(", "    db: AsyncSession,", "    *,", "    article_id: UUID,", "    classification_method: str,", "    origin_activity_id: Optional[UUID],", "    rejected_match_info: Optional[Dict[str, Any]] = None,", ") -> SourceClassification:", "    \"\"\"Build a singleton group + classification row for ``article_id``.", "", "    Caller MUST hold the per-article advisory lock for ``article_id`` and is", "    responsible for committing. Flushes pending rows so the new group id is", "    usable by the caller; does not commit. The advisory lock is xact-scoped", "    and releases on the caller's commit/rollback \u2014 so callers should commit", "    promptly after this helper returns to avoid extending lock-hold time.", "", "    If a classification row already exists for ``article_id`` (a concurrent", "    writer won the race under the same lock), this returns the existing row", "    without creating a new group. The check exists because callers in", "    ``attach_article_to_group`` already perform the same lookup above, and", "    callers in ``_resolve_or_materialize_group_for_article`` perform a", "    pre-lock optimistic check; the in-helper recheck is the authoritative", "    one under the lock.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param article_id: Article id to seed the singleton with.", "    :type article_id: UUID", "    :param classification_method: Identifier for the classification approach.", "    :type classification_method: str", "    :param origin_activity_id: L2 activity id recorded on the new group row.", "    :type origin_activity_id: Optional[UUID]", "    :param rejected_match_info: Adjudication for a match that was found and", "        rejected, persisted to the row's ``match_info``. Carries the verifier's", "        verdict keys only, never lineage. ``None`` for an article that simply", "        matched nothing, which keeps ``match_info`` NULL as before.", "    :type rejected_match_info: Optional[Dict[str, Any]]", "    :return: Classification row for ``article_id`` (newly created or pre-existing).", "    :rtype: SourceClassification", "    :raises DatabaseWriteException: On underlying write or lookup failure.", "    \"\"\"", "    existing = await get_source_classification_for_article(db, article_id)", "    if existing is not None:", "        return existing", "", "    new_group = SourceClassificationGroup(", "        primary_article_id=article_id,", "        seed_article_id=article_id,", "        origin_activity_id=origin_activity_id,", "        member_count=0,", "    )", "    db.add(new_group)", "    await db.flush()", "", "    row = await _upsert_source_classification_record(", "        db,", "        article_id=article_id,", "        syndication_group_id=new_group.id,", "        similarity_score=None,", "        matched_article_id=None,", "        classification_method=classification_method,", "        match_info=rejected_match_info,", "    )", "    await db.execute(", "        update(SourceClassificationGroup)", "        .where(SourceClassificationGroup.id == new_group.id)", "        .values(", "            member_count=SourceClassificationGroup.member_count + 1,", "            updated_at=func.now(),", "        )", "    )", "    return row", "", "", "async def _join_existing_group_locked(", "    db: AsyncSession,", "    *,", "    article_id: UUID,", "    frozen_group_id: UUID,", "    matched_article_id: Optional[UUID],", "    similarity_score: Optional[float],", "    classification_method: str,", "    match_info: Optional[Dict[str, Any]] = None,", ") -> SourceClassification:", "    \"\"\"Attach ``article_id`` to a pre-resolved syndication group.", "", "    Caller MUST hold the per-article advisory lock for ``article_id`` and is", "    responsible for committing (mirrors the ``_create_singleton_group_locked``", "    contract). Takes the parent group row with ``SELECT \u2026 FOR UPDATE`` so", "    member-count bumps and primary recomputation happen under exclusive", "    access, then optionally recomputes the primary when the new attachee", "    could displace it (see ``_new_member_could_displace_primary``).", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param article_id: Article id being attached.", "    :type article_id: UUID", "    :param frozen_group_id: Pre-resolved group id to attach to.", "    :type frozen_group_id: UUID", "    :param matched_article_id: Article id matched for syndication, recorded", "        as lineage on the row.", "    :type matched_article_id: Optional[UUID]", "    :param similarity_score: Similarity score for the syndication match.", "    :type similarity_score: Optional[float]", "    :param classification_method: Identifier for the classification approach used.", "    :type classification_method: str", "    :return: Classification row for ``article_id``.", "    :rtype: SourceClassification", "    :raises DatabaseWriteException: When ``frozen_group_id`` does not exist,", "        or on underlying write or lookup failure.", "    \"\"\"", "    lock_stmt = (", "        select(SourceClassificationGroup.id)", "        .where(SourceClassificationGroup.id == frozen_group_id)", "        .with_for_update()", "    )", "    resolved = (await db.execute(lock_stmt)).scalar_one_or_none()", "    if resolved is None:", "        raise DatabaseWriteException(", "            \"Frozen syndication group id does not exist\",", "            article_id=article_id,", "            frozen_group_id=str(frozen_group_id),", "        )", "    row = await _upsert_source_classification_record(", "        db,", "        article_id=article_id,", "        syndication_group_id=resolved,", "        similarity_score=similarity_score,", "        matched_article_id=matched_article_id,", "        classification_method=classification_method,", "        match_info=match_info,", "    )", "    await db.execute(", "        update(SourceClassificationGroup)", "        .where(SourceClassificationGroup.id == resolved)", "        .values(", "            member_count=SourceClassificationGroup.member_count + 1,", "            updated_at=func.now(),", "        )", "    )", "    # Skip the O(group_size) recompute when this attach can't possibly change", "    # the primary. Typical syndication-coverage flow (later wire-service pickup", "    # of an already-grouped story) hits the skip path; only \"earlier-than-current", "    # arrives later\" or mixed-dated/undated cases pay the full recompute cost.", "    if await _new_member_could_displace_primary(db, resolved, article_id):", "        await reevaluate_group_primary(db, resolved)", "    return row", "", "", "async def attach_article_to_group(", "    db: AsyncSession,", "    *,", "    article_id: UUID,", "    matched_article_id: Optional[UUID],", "    similarity_score: Optional[float],", "    classification_method: str,", "    frozen_group_id: Optional[UUID] = None,", "    origin_activity_id: Optional[UUID] = None,", "    match_info: Optional[Dict[str, Any]] = None,", "    rejected_match_info: Optional[Dict[str, Any]] = None,", ") -> SourceClassification:", "    \"\"\"Attach an article's classification row to a syndication group.", "", "    Single entry point for original and syndicated writes. Behaviour:", "", "    - ``frozen_group_id`` set: ``SELECT \u2026 FOR UPDATE`` that group, attach this", "      article to it. ``matched_article_id`` is recorded as lineage metadata.", "    - ``frozen_group_id`` and ``matched_article_id`` both None: create a new", "      singleton group with this article as primary.", "", "    Callers attaching a syndicated article MUST pre-resolve the target group", "    (via ``resolve_retry_syndication_group_id`` /", "    ``_resolve_or_materialize_group_for_article``) and pass it as", "    ``frozen_group_id``. Passing ``matched_article_id`` without", "    ``frozen_group_id`` is rejected.", "", "    Concurrency / convergence", "    -------------------------", "    When ``matched_article_id`` is provided this helper takes advisory locks", "    on *both* ``article_id`` and ``matched_article_id`` (sorted by id to", "    avoid deadlock under crossed concurrent writes). Inside the dual lock,", "    the matched article's current group is re-read; if it diverges from", "    ``frozen_group_id`` \u2014 meaning a concurrent worker pre-resolved a", "    different singleton between this attach's pre-resolve and now \u2014 the two", "    groups are merged via ``_merge_syndication_groups`` and the merged", "    group becomes the attach target. Same merge fires if ``article_id``", "    already has a classification row in a different group. The net effect:", "    crossed concurrent writes (A\u2192B and B\u2192A in parallel) converge on one", "    group rather than fragmenting into two singletons.", "", "    The resolved parent group row is also taken with ``FOR UPDATE`` (inside", "    ``_join_existing_group_locked``) so member counts and primary", "    recomputation happen under exclusive access.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param article_id: Article id being attached.", "    :type article_id: UUID", "    :param matched_article_id: Article id matched for syndication, recorded as", "        lineage on the row. Required to be paired with ``frozen_group_id``.", "    :type matched_article_id: Optional[UUID]", "    :param similarity_score: Similarity score for the syndication match, when known.", "    :type similarity_score: Optional[float]", "    :param classification_method: Identifier for the classification approach used.", "    :type classification_method: str", "    :param frozen_group_id: Pre-resolved group id from retry-context freeze.", "    :type frozen_group_id: Optional[UUID]", "    :param origin_activity_id: L2 activity id that originated this attach call;", "        recorded on the parent group row when a new group is created. Ignored", "        when joining an existing group.", "    :type origin_activity_id: Optional[UUID]", "    :param match_info: Optional audit blob persisted on the classification row's", "        ``match_info`` JSONB. Carries the dedup match details and any borderline-", "        verifier verdict. Only applied on the join path (where ``frozen_group_id``", "        is set) \u2014 singleton creation has no match to record.", "    :type match_info: Optional[Dict[str, Any]]", "    :param rejected_match_info: The singleton-path counterpart to ``match_info``:", "        the adjudication for a match that was found and then rejected, persisted", "        to the new row's ``match_info`` JSONB. Carries the verifier's verdict keys", "        only \u2014 never ``matched_article_id``, ``best_match`` or dedup chunk detail,", "        because a UNIQUE row has no lineage to honour. ``None`` for an article that", "        simply matched nothing, so ordinary singletons keep ``match_info`` NULL.", "        Ignored on the join path, where ``match_info`` is the channel.", "    :type rejected_match_info: Optional[Dict[str, Any]]", "    :return: Persisted classification row for ``article_id``.", "    :rtype: SourceClassification", "    :raises DatabaseWriteException: When ``matched_article_id`` is set without", "        ``frozen_group_id``, or on any underlying write or lookup failure.", "    :raises DatabaseCommitException: On commit failure.", "    \"\"\"", "    if matched_article_id is not None and frozen_group_id is None:", "        raise DatabaseWriteException(", "            \"attach_article_to_group requires frozen_group_id when matched_article_id is set; \"", "            \"callers must pre-resolve the target group via resolve_retry_syndication_group_id\",", "            article_id=article_id,", "            matched_article_id=str(matched_article_id),", "        )", "", "    # Always lock article_id; also lock matched_article_id when distinct so", "    # that the convergence merge below has both articles' state pinned for", "    # the duration of attach. Sorted by str so concurrent workers attaching", "    # the same pair (A\u2192B vs B\u2192A) acquire in identical order \u2014 no deadlock.", "    lock_article_ids = sorted(", "        {article_id, *([matched_article_id] if matched_article_id is not None else [])},", "        key=str,", "    )", "", "    try:", "        async with AsyncExitStack() as article_lock_stack:", "            for lock_article_id in lock_article_ids:", "                await article_lock_stack.enter_async_context(", "                    pg_advisory_xact_lock(", "                        db, url_to_lock_key(f\"syndication-article:{lock_article_id}\")", "                    )", "                )", "", "            # Convergence step: under both locks, re-check whether the matched", "            # article's current group still matches the pre-resolved frozen", "            # group. A concurrent worker may have pre-resolved a different", "            # singleton between our pre-resolve and now; if so, merge.", "            target_group_id = frozen_group_id", "            if matched_article_id is not None and frozen_group_id is not None:", "                matched_current = await get_source_classification_for_article(", "                    db, matched_article_id", "                )", "                if (", "                    matched_current is not None", "                    and matched_current.syndication_group_id != frozen_group_id", "                ):", "                    logger.info(", "                        \"attach_article_to_group: matched article in different group \"", "                        \"than pre-resolved \u2014 merging (crossed-write convergence)\",", "                        article_id=str(article_id),", "                        matched_article_id=str(matched_article_id),", "                        pre_resolved_group_id=str(frozen_group_id),", "                        matched_current_group_id=str(matched_current.syndication_group_id),", "                    )", "                    target_group_id = await _merge_syndication_groups(", "                        db,", "                        group_id_a=frozen_group_id,", "                        group_id_b=matched_current.syndication_group_id,", "                    )", "                    # Chase a 3-way race: if matched_current's group was already", "                    # being merged into a third group C when our merge took its", "                    # locks, ``_merge_syndication_groups`` may have observed a", "                    # missing winner and fallen back to returning the surviving", "                    # loser. That leaves the matched article in C while", "                    # target_group_id points elsewhere \u2014 silent fragmentation.", "                    # Re-read and re-merge until matched lives in target_group_id", "                    # or the bounded retry budget is exhausted.", "                    converged = False", "                    for _ in range(_MAX_CONVERGENCE_ITERATIONS):", "                        db.expire(matched_current)", "                        matched_current = await get_source_classification_for_article(", "                            db, matched_article_id", "                        )", "                        if (", "                            matched_current is None", "                            or matched_current.syndication_group_id == target_group_id", "                        ):", "                            converged = True", "                            break", "                        logger.info(", "                            \"attach_article_to_group: matched article drifted to a \"", "                            \"third group post-merge \u2014 chasing convergence\",", "                            article_id=str(article_id),", "                            matched_article_id=str(matched_article_id),", "                            target_group_id=str(target_group_id),", "                            matched_current_group_id=str(matched_current.syndication_group_id),", "                        )", "                        target_group_id = await _merge_syndication_groups(", "                            db,", "                            group_id_a=target_group_id,", "                            group_id_b=matched_current.syndication_group_id,", "                        )", "                    if not converged:", "                        logger.warning(", "                            \"attach_article_to_group: convergence did not stabilize \"", "                            \"within max iterations \u2014 matched article may remain in \"", "                            \"a different group\",", "                            article_id=str(article_id),", "                            matched_article_id=str(matched_article_id),", "                            max_iterations=_MAX_CONVERGENCE_ITERATIONS,", "                            target_group_id=str(target_group_id),", "                            last_observed_matched_group_id=(", "                                str(matched_current.syndication_group_id)", "                                if matched_current is not None", "                                else None", "                            ),", "                        )", "", "            existing = await get_source_classification_for_article(db, article_id)", "            if existing is not None:", "                # Race already resolved by another writer for ``article_id``.", "                # If that writer landed it in a different group than our", "                # target, merge so the two articles still converge.", "                if target_group_id is not None and existing.syndication_group_id != target_group_id:", "                    logger.info(", "                        \"attach_article_to_group: existing classification in different group \"", "                        \"than target \u2014 merging (crossed-write convergence)\",", "                        article_id=str(article_id),", "                        existing_group_id=str(existing.syndication_group_id),", "                        target_group_id=str(target_group_id),", "                    )", "                    target_group_id = await _merge_syndication_groups(", "                        db,", "                        group_id_a=target_group_id,", "                        group_id_b=existing.syndication_group_id,", "                    )", "                    # _merge_syndication_groups moves SC rows via a Core bulk", "                    # UPDATE that doesn't invalidate the ORM identity map.", "                    # Expire the cached instance so the re-read returns the", "                    # post-merge syndication_group_id rather than the stale", "                    # (now-deleted-loser) value.", "                    db.expire(existing)", "                    refreshed = await get_source_classification_for_article(db, article_id)", "                    if refreshed is not None:", "                        existing = refreshed", "", "                # Commit any merge work done above; if no merge fired this", "                # is a clean-transaction no-op that still releases the", "                # advisory locks held by this scope. Rollback on failure", "                # is handled by the outer ``except DatabaseWriteException``", "                # clause \u2014 see the comment at the function-level catch.", "                try:", "                    await db.commit()", "                except Exception as e:", "                    raise DatabaseCommitException(", "                        f\"Failed to commit attach_article_to_group convergence merge \"", "                        f\"(caused by >>> {e!r})\",", "                        article_id=article_id,", "                        syndication_group_id=str(existing.syndication_group_id),", "                    ) from e", "                return existing", "", "            final_row: SourceClassification", "            if target_group_id is not None:", "                final_row = await _join_existing_group_locked(", "                    db,", "                    article_id=article_id,", "                    frozen_group_id=target_group_id,", "                    matched_article_id=matched_article_id,", "                    similarity_score=similarity_score,", "                    classification_method=classification_method,", "                    match_info=match_info,", "                )", "            else:", "                final_row = await _create_singleton_group_locked(", "                    db,", "                    article_id=article_id,", "                    classification_method=classification_method,", "                    origin_activity_id=origin_activity_id,", "                    rejected_match_info=rejected_match_info,", "                )", "", "            try:", "                await db.commit()", "            except Exception as e:", "                # Rollback is intentionally NOT done here; the outer", "                # ``except DatabaseWriteException`` clause handles cleanup", "                # once for every error path. Doing it twice (here + outer)", "                # used to work only by virtue of except-clause ordering,", "                # which made the contract fragile to reorders.", "                raise DatabaseCommitException(", "                    f\"Failed to commit attach_article_to_group write (caused by >>> {e!r})\",", "                    article_id=article_id,", "                    syndication_group_id=str(final_row.syndication_group_id),", "                ) from e", "", "            return final_row", "    except DatabaseWriteException:", "        # Single rollback handles every error path that exits this scope \u2014", "        # commit failures (raised as DatabaseCommitException, a subclass),", "        # nested flush-only helpers raising mid-attach, and unexpected", "        # exceptions re-wrapped below. No except-clause ordering is needed:", "        # ``DatabaseWriteException`` catches its own subclasses uniformly.", "        await safe_rollback(db)", "        raise", "    except Exception as e:", "        await safe_rollback(db)", "        raise DatabaseWriteException(", "            f\"Failed to attach article to syndication group (caused by >>> {e!r})\",", "            article_id=article_id,", "            matched_article_id=matched_article_id,", "            similarity_score=similarity_score,", "        ) from e", "", "", "async def resolve_retry_syndication_group_id(", "    db: AsyncSession,", "    *,", "    is_syndicated: bool,", "    best_match_article_id: Optional[UUID],", "    recovering_missing_classification: bool,", "    retry_frozen_group_id: Optional[UUID],", "    activity_id: UUID,", "    response_id: UUID,", "    classification: str,", ") -> Optional[UUID]:", "    \"\"\"Resolve and persist syndication group context used by retry recovery paths.", "", "    When the matched article has no classification row yet, a singleton group", "    is materialized for it via ``_resolve_or_materialize_group_for_article``", "    so the freeze step has a concrete group id to persist.", "", "    :param db: Active datalake async session.", "    :type db: AsyncSession", "    :param is_syndicated: Whether the current classification is \"syndicated\".", "    :type is_syndicated: bool", "    :param best_match_article_id: Best-match article id from similarity search.", "    :type best_match_article_id: Optional[UUID]", "    :param recovering_missing_classification: Whether this is a retry recovery path.", "    :type recovering_missing_classification: bool", "    :param retry_frozen_group_id: Previously-frozen group id from retry context.", "    :type retry_frozen_group_id: Optional[UUID]", "    :param activity_id: L2 activity id (used in error context).", "    :type activity_id: UUID", "    :param response_id: Response id keying the retry-state row.", "    :type response_id: UUID", "    :param classification: Classification label (used in error context).", "    :type classification: str", "    :return: Resolved frozen group id, or None when not syndicated.", "    :rtype: Optional[UUID]", "    :raises DatabaseWriteException: When syndicated classification lacks a best match.", "    :raises DatabaseCommitException: When the recovery-fallback commit fails.", "    \"\"\"", "    if not is_syndicated:", "        return None", "    if best_match_article_id is None:", "        raise DatabaseWriteException(", "            \"Similarity classification returned syndicated but no best_match was found\",", "            activity_id=activity_id,", "            classification=classification,", "        )", "", "    if recovering_missing_classification:", "        if retry_frozen_group_id is not None:", "            return retry_frozen_group_id", "        fallback_group = await _resolve_or_materialize_group_for_article(", "            db, best_match_article_id, origin_activity_id=activity_id", "        )", "        # Commit any pending singleton materialization here \u2014 the fallback", "        # path intentionally does NOT re-persist retry context (the warning", "        # below acknowledges this drift), so no later helper commits for us.", "        # The commit also releases the per-article advisory lock acquired", "        # inside _resolve_or_materialize_group_for_article.", "        try:", "            await db.commit()", "        except Exception as e:", "            await safe_rollback(db)", "            raise DatabaseCommitException(", "                f\"Failed to commit retry-recovery fallback singleton materialization \"", "                f\"(caused by >>> {e!r})\",", "                activity_id=activity_id,", "                response_id=response_id,", "                matched_article_id=best_match_article_id,", "                classification=classification,", "            ) from e", "        logger.warning(", "            \"Retry recovery missing frozen syndication group in response context; \"", "            \"falling back to current matched lineage\",", "            activity_id=str(activity_id),", "            response_id=str(response_id),", "            matched_article_id=str(best_match_article_id),", "        )", "        return fallback_group", "", "    # Non-recovery path: fuse the singleton materialization (if any) with the", "    # retry-context write into a single commit via persist_layer_two_retry_context.", "    resolved_group_id = await _resolve_or_materialize_group_for_article(", "        db, best_match_article_id, origin_activity_id=activity_id", "    )", "    await persist_layer_two_retry_context(", "        db,", "        response_id=response_id,", "        frozen_syndication_group_id=resolved_group_id,", "    )", "    return resolved_group_id", "", "", "async def _resolve_or_materialize_group_for_article(", "    db: AsyncSession,", "    article_id: UUID,", "    *,", "    origin_activity_id: Optional[UUID] = None,", ") -> UUID:", "    \"\"\"Return the group id for an article's classification row, materializing one when missing.", "", "    Does NOT commit when it materializes. Caller MUST commit before doing", "    further work, because the per-article advisory lock acquired here is", "    xact-scoped and only releases on commit/rollback. The non-recovery caller", "    (``resolve_retry_syndication_group_id``) commits via the following", "    ``persist_layer_two_retry_context`` call, fusing the singleton creation", "    and the retry-context write into a single transaction (one commit instead", "    of two, and no inconsistency window where the singleton exists but no", "    frozen-context row points at it).", "    \"\"\"", "    matched_row = await get_source_classification_for_article(db, article_id)", "    if matched_row is not None:", "        return matched_row.syndication_group_id", "    async with pg_advisory_xact_lock(db, url_to_lock_key(f\"syndication-article:{article_id}\")):", "        singleton = await _create_singleton_group_locked(", "            db,", "            article_id=article_id,", "            classification_method=CLASSIFICATION_METHOD_LAZY_SINGLETON,", "            origin_activity_id=origin_activity_id,", "        )", "        return singleton.syndication_group_id"], "blocks": [{"start": 1, "end": 67, "label": "Imports and module setup"}, {"start": 68, "end": 85, "label": "def get_source_classification_for_article"}, {"start": 86, "end": 104, "label": "def read_layer_two_retry_context"}, {"start": 105, "end": 143, "label": "def persist_layer_two_retry_context"}, {"start": 144, "end": 175, "label": "def ensure_layer_two_retry_similarity_cutoff"}, {"start": 176, "end": 254, "label": "def _upsert_source_classification_record"}, {"start": 255, "end": 291, "label": "def _pick_primary_article_id"}, {"start": 292, "end": 354, "label": "def _new_member_could_displace_primary"}, {"start": 355, "end": 416, "label": "def reevaluate_group_primary"}, {"start": 417, "end": 550, "label": "def _merge_syndication_groups"}, {"start": 551, "end": 624, "label": "def _create_singleton_group_locked"}, {"start": 625, "end": 699, "label": "def _join_existing_group_locked"}, {"start": 700, "end": 978, "label": "def attach_article_to_group"}, {"start": 979, "end": 1070, "label": "def resolve_retry_syndication_group_id"}, {"start": 1071, "end": 1098, "label": "def _resolve_or_materialize_group_for_article"}], "lineCount": 1098, "sha256": "1bc46d4376f0ca0a7a174fbaadfdcbb623754f446cb990d3d0b9df07a39b5098", "endsWithNewline": true});
